const inquiry=document.getElementById('inquiry');
function trackConsulting(name,params){if(typeof window.gtag==='function')window.gtag('event',name,params||{});}
document.querySelectorAll('a[download]').forEach(link=>link.addEventListener('click',()=>trackConsulting('review_resource_download',{resource:link.getAttribute('href')})));
document.getElementById('send').addEventListener('click',()=>trackConsulting('consulting_email_opened',{service:document.getElementById('service').value}));
inquiry.addEventListener('submit',()=>trackConsulting('consulting_inquiry_prepared',{service:document.getElementById('service').value}));
inquiry.addEventListener('submit',event=>{event.preventDefault();const data=new FormData(inquiry);const subject='Architecture consulting: '+data.get('service');const body=['Name: '+data.get('name'),'Email: '+data.get('email'),'Company: '+data.get('company'),'Service: '+data.get('service'),'','Project context:',data.get('context')].join('\n');document.getElementById('message').value='To: internetapps.net@gmail.com\nSubject: '+subject+'\n\n'+body;document.getElementById('send').href='mailto:internetapps.net@gmail.com?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);document.getElementById('draft').hidden=false;document.getElementById('status').textContent='Draft ready. Review it, then open your email app or copy the message.';document.getElementById('message').focus();});
document.getElementById('copy').addEventListener('click',async()=>{const message=document.getElementById('message');try{await navigator.clipboard.writeText(message.value);document.getElementById('status').textContent='Draft copied. Paste it into your email service.';}catch{message.focus();message.select();document.getElementById('status').textContent='Copy the selected draft into your email service.';}});
